update public.learning_paths
set
  title = 'Critical Thinking / Logic',
  goal = 'Critical Thinking / Logic',
  summary = 'Students identify, reconstruct, and evaluate arguments in ordinary language, academic writing, media, and public debate; distinguish deductive validity, soundness, inductive strength, cogency, causal support, analogy, and explanatory reasoning; use basic propositional logic, truth tables, and proof patterns; recognize fallacies, cognitive biases, rhetorical manipulation, ambiguity, and weak evidence; evaluate sources, testimony, expertise, probability, statistics, scientific claims, and misinformation; and write clear analytical arguments with objections, replies, evidence, citations, and revision.',
  data = $ctljson${"slug": "critical-thinking-logic", "title": "Critical Thinking / Logic", "description": "Students identify, reconstruct, and evaluate arguments in ordinary language, academic writing, media, and public debate; distinguish deductive validity, soundness, inductive strength, cogency, causal support, analogy, and explanatory reasoning; use basic propositional logic, truth tables, and proof patterns; recognize fallacies, cognitive biases, rhetorical manipulation, ambiguity, and weak evidence; evaluate sources, testimony, expertise, probability, statistics, scientific claims, and misinformation; and write clear analytical arguments with objections, replies, evidence, citations, and revision.", "topics": [{"id": "0da44897-73bd-4589-bf6c-812ad3dfd9f1", "type": "topic", "title": "What Critical Thinking Is: Inquiry, Intellectual Virtues, and Standards", "description": "Establish critical thinking as disciplined inquiry guided by clarity, accuracy, relevance, fairness, and intellectual humility.", "children": [{"id": "8a17f527-3b91-452b-aced-7fb87d611582", "type": "subtopic", "title": "Disciplined inquiry", "children": [{"id": "f7dc136c-d0f2-40dc-ba24-16a777573abc", "type": "concept", "title": "Questions and problems"}, {"id": "743ebc86-da3a-44a5-b7d1-7dbcdeef1b59", "type": "concept", "title": "Open-minded investigation"}, {"id": "d1c05e9d-2f68-4f3d-8f17-d994b1de9eb7", "type": "concept", "title": "Standards of evaluation"}, {"id": "d5644cda-5f8e-40bb-9dff-0ae95b14d8aa", "type": "concept", "title": "Revision of belief"}], "description": "Why it matters: The point is to treat thinking as a practice that can be improved, not a personality trait someone either has or lacks."}, {"id": "00ed2f57-d45b-4e28-8ae2-3ab9bd6eeb5a", "type": "subtopic", "title": "Intellectual virtues", "children": [{"id": "1c7d07aa-e3de-4f77-92eb-c7e08d550a21", "type": "concept", "title": "Intellectual humility"}, {"id": "0144f872-fe4c-422c-9f7e-980a1b33d8f6", "type": "concept", "title": "Fair-mindedness"}, {"id": "46d8f12e-dc5d-40a6-8931-e3e73bdba76b", "type": "concept", "title": "Curiosity"}, {"id": "a7381080-394f-4379-90ee-fede7f402e5f", "type": "concept", "title": "Courage under disagreement"}], "description": "Why it matters: Good reasoning depends on habits such as humility, courage, charity, patience, and willingness to follow evidence."}, {"id": "9c128778-d25c-4cbf-b6bc-1d777df3c4b1", "type": "subtopic", "title": "Standards of thinking", "children": [{"id": "da2771f5-02cf-4d3f-93d4-d391282254ff", "type": "concept", "title": "Clarity"}, {"id": "870c5300-ebb8-4dcd-ab3c-67bd62770e4c", "type": "concept", "title": "Accuracy"}, {"id": "818341b2-cf6e-4386-ab4f-ad92b851682f", "type": "concept", "title": "Precision"}, {"id": "926df1b9-c4e0-45b2-b36d-06445b7c11b3", "type": "concept", "title": "Relevance and significance"}], "description": "Why it matters: Students need shared criteria for judging reasoning quality across subjects."}]}, {"id": "8a867e62-21f1-470e-9ab6-80140219f23c", "type": "topic", "title": "Arguments, Claims, Reasons, Conclusions, and Argument Reconstruction", "description": "Learn to identify, extract, and reconstruct arguments from ordinary speech, academic texts, media, and public debate.", "children": [{"id": "7233b927-488d-4b11-9faa-65f311be6052", "type": "subtopic", "title": "Argument identification", "children": [{"id": "4a2e5234-f8ff-479c-b116-abeba8023c99", "type": "concept", "title": "Claims"}, {"id": "12ea4bbf-0a43-4d11-b064-2f2496c1d4e4", "type": "concept", "title": "Reasons"}, {"id": "e1a2d674-cbc5-47b4-8208-9c62f02e3e59", "type": "concept", "title": "Conclusions"}, {"id": "480b69f5-6b77-42e0-94d3-0549b21170fe", "type": "concept", "title": "Indicator words"}], "description": "Why it matters: Students learn to separate arguments from descriptions, explanations, reports, and emotional reactions."}, {"id": "b45db251-3f1b-4f32-9f9d-c53ba4e4fde6", "type": "subtopic", "title": "Argument structure", "children": [{"id": "8dddca50-4024-4869-a9b9-5d83c4d5649f", "type": "concept", "title": "Linked reasons"}, {"id": "2a62435b-e715-4828-a579-db6432adb3a4", "type": "concept", "title": "Independent reasons"}, {"id": "295278dc-652c-481b-9aa8-fc844bd98bd0", "type": "concept", "title": "Subconclusions"}, {"id": "6278a63c-b294-47d0-80fe-b655400d05c8", "type": "concept", "title": "Implicit premises"}], "description": "Why it matters: Real arguments often hide premises, combine reasons, or support multiple conclusions."}, {"id": "c5015fdd-2877-4922-bb0d-bbad1b74fb00", "type": "subtopic", "title": "Reconstruction", "children": [{"id": "1e8e8c18-4518-4cef-a63e-6940b1a31281", "type": "concept", "title": "Principle of charity"}, {"id": "9e700d39-2f16-416a-a3ed-5c7f0d80a68e", "type": "concept", "title": "Standard form"}, {"id": "3860822d-5fdd-4651-99d3-576e9f669f1a", "type": "concept", "title": "Missing assumptions"}, {"id": "22bad05e-6524-4389-a9c4-ea81c9e6f246", "type": "concept", "title": "Context-sensitive interpretation"}], "description": "Why it matters: Reconstruction makes an argument clear enough to evaluate fairly."}]}, {"id": "574b2d61-ef76-46b9-95ce-618ab39f9641", "type": "topic", "title": "Validity, Soundness, Strength, Cogency, and Core Logical Vocabulary", "description": "Build the core logic vocabulary needed to evaluate whether reasons actually support conclusions.", "children": [{"id": "a930b1b5-a638-410f-8eb7-180324019acf", "type": "subtopic", "title": "Deductive evaluation", "children": [{"id": "a53ca9b4-e098-4df1-8da4-d7d44e9d4e58", "type": "concept", "title": "Validity"}, {"id": "ec4722b3-2795-4581-b710-e770c02b746a", "type": "concept", "title": "Soundness"}, {"id": "6c7b7184-80e4-4fbd-8a79-e9a8799353eb", "type": "concept", "title": "Counterexamples"}, {"id": "848b24d3-efe2-4bc5-9288-ca0714fe643a", "type": "concept", "title": "Necessary versus sufficient conditions"}], "description": "Why it matters: Deductive standards ask whether the conclusion must follow if the premises are true."}, {"id": "590bc905-7455-4374-927a-e11b30e8369d", "type": "subtopic", "title": "Inductive evaluation", "children": [{"id": "c45f0bf8-2b8a-480e-bc40-cc2b3b87335a", "type": "concept", "title": "Strength"}, {"id": "9d3402aa-af6e-4641-99f3-52d86ff5554f", "type": "concept", "title": "Cogency"}, {"id": "588173e0-4245-4927-b023-b4f7155c4839", "type": "concept", "title": "Sample size"}, {"id": "7d720755-2f8c-40fb-8cce-61a360da2a69", "type": "concept", "title": "Representativeness"}], "description": "Why it matters: Inductive standards ask whether the premises make the conclusion likely or reasonable."}, {"id": "8c23765f-cd87-4159-839f-109a00f50724", "type": "subtopic", "title": "Logical vocabulary", "children": [{"id": "a58a46fb-cf7a-4eef-8ce3-74d1972725d1", "type": "concept", "title": "Consistency"}, {"id": "ef0efc7e-97ba-4535-bd5c-973ea24d6dcc", "type": "concept", "title": "Contradiction"}, {"id": "c9777015-e62d-4c9b-b322-fbbdb6cc844f", "type": "concept", "title": "Entailment"}, {"id": "bf9ece25-41c0-4ec3-b35d-75209f980386", "type": "concept", "title": "Burden of proof"}], "description": "Why it matters: Precise vocabulary helps students say exactly what is wrong or right with an argument."}]}, {"id": "602c9e84-39ee-43f4-9f96-39e4d176b68c", "type": "topic", "title": "Deductive Reasoning: Propositional Logic, Truth Tables, and Natural Deduction", "description": "Introduce formal tools for evaluating deductive validity and recognizing argument forms.", "children": [{"id": "b97e4562-d46a-4393-93a9-6ab9f6d50237", "type": "subtopic", "title": "Propositional logic", "children": [{"id": "4001ca54-da34-4e73-9c07-4417709b2da2", "type": "concept", "title": "Atomic propositions"}, {"id": "3591c63d-820e-451d-8bc1-a3cd1d041885", "type": "concept", "title": "Connectives"}, {"id": "e444a9b5-3ace-4b4e-8d15-6882f3d9cfff", "type": "concept", "title": "Conditionals"}, {"id": "bcd848d9-b8d9-4029-8d66-28b8f636d144", "type": "concept", "title": "Biconditionals"}], "description": "Why it matters: Formal logic helps students see argument structure apart from distracting subject matter."}, {"id": "f907daa6-2337-4dcb-b12a-a3a745e30938", "type": "subtopic", "title": "Truth tables", "children": [{"id": "a9f954de-057b-4ed9-8c8c-b3aab7a9d3f3", "type": "concept", "title": "Truth-functional analysis"}, {"id": "8cd379c2-21b1-41b1-9bb6-dc0b5ae776eb", "type": "concept", "title": "Tautologies"}, {"id": "6460f4df-d613-4f86-8911-c1dc37dc3ca2", "type": "concept", "title": "Contradictions"}, {"id": "8e47ba63-0d9a-4932-ada7-9bfa6b25146f", "type": "concept", "title": "Validity testing"}], "description": "Why it matters: Truth tables provide a mechanical test for validity in propositional logic."}, {"id": "afc1826c-ebf3-48bf-9705-1f42d1accb65", "type": "subtopic", "title": "Proof methods", "children": [{"id": "054803c9-a8cd-4067-a600-03684159c69e", "type": "concept", "title": "Modus ponens"}, {"id": "1f67ee3f-a5e2-4940-9166-3030e7f32ca1", "type": "concept", "title": "Modus tollens"}, {"id": "44046285-10b5-4f27-a802-2a56846260ac", "type": "concept", "title": "Conditional proof"}, {"id": "a0218ca2-f1d4-49e1-b078-a6803f1fd7f1", "type": "concept", "title": "Reductio"}], "description": "Why it matters: Natural deduction introduces disciplined step-by-step derivation."}]}, {"id": "639ea09e-b483-4ebe-b548-5dd98820742c", "type": "topic", "title": "Inductive, Abductive, Analogical, and Causal Reasoning", "description": "Evaluate non-deductive arguments that support conclusions with probability, explanation, comparison, and causal inference.", "children": [{"id": "851758af-24b5-4016-871f-d32ac471c248", "type": "subtopic", "title": "Induction", "children": [{"id": "12810580-46ff-4c76-9a7c-11f6dc9f7c14", "type": "concept", "title": "Enumerative induction"}, {"id": "f0799a64-a7dd-4e53-bc89-a42df6658b2d", "type": "concept", "title": "Statistical generalization"}, {"id": "fb90d7fe-0d58-44e5-92c2-e43ab87b4262", "type": "concept", "title": "Sampling bias"}, {"id": "d02be8d0-51c1-4c22-bcc8-dd40700622f2", "type": "concept", "title": "Confidence and uncertainty"}], "description": "Why it matters: Induction underlies generalization from observations but must be evaluated carefully."}, {"id": "b9e407e7-2ce6-4375-813c-0051f79e7341", "type": "subtopic", "title": "Abduction", "children": [{"id": "e184ee57-c2ee-4fed-8e29-c695d0d608d5", "type": "concept", "title": "Explanatory scope"}, {"id": "482eac79-54bb-4349-89af-3eabd9b747f0", "type": "concept", "title": "Simplicity"}, {"id": "f78ee973-4fb2-4951-9882-825486533ef9", "type": "concept", "title": "Coherence"}, {"id": "defbfc8c-70ab-42b0-a491-fd1e401bb85a", "type": "concept", "title": "Rival explanations"}], "description": "Why it matters: Inference to the best explanation helps students compare hypotheses instead of grabbing the first plausible story."}, {"id": "29214b1c-4dec-4266-a4e2-79f01c01d74c", "type": "subtopic", "title": "Analogy and causation", "children": [{"id": "09529494-dc3f-46ba-84b4-61a989df150a", "type": "concept", "title": "Relevant similarity"}, {"id": "5754a816-1cef-46c6-9099-c20fd56af78a", "type": "concept", "title": "False analogy"}, {"id": "2ed80c15-f594-4b2b-8151-28f9bfc3ec51", "type": "concept", "title": "Correlation versus causation"}, {"id": "6ca6e25e-74d4-4717-bb6b-9c0ed4b08bb7", "type": "concept", "title": "Confounding variables"}], "description": "Why it matters: Analogies and causal claims are powerful but easy to overextend."}]}, {"id": "9d2a0e31-04cd-4b48-b7d2-ec4c2ff3034f", "type": "topic", "title": "Informal Fallacies, Cognitive Biases, and Misleading Persuasion", "description": "Identify common failures of reasoning and the psychological traps that make bad arguments feel persuasive.", "children": [{"id": "3ee4c377-0bee-462d-9917-df2203dba00f", "type": "subtopic", "title": "Fallacies of relevance", "children": [{"id": "9712e761-b87c-4b1c-9251-c20f1df00fc0", "type": "concept", "title": "Ad hominem"}, {"id": "d3181717-99ee-42bf-b42f-dfb81e1e8b96", "type": "concept", "title": "Straw man"}, {"id": "11ac89b1-bc41-47a0-b1df-57fdf3c53271", "type": "concept", "title": "Red herring"}, {"id": "dc661f03-37cb-4e69-bf1d-16d9c4bf5008", "type": "concept", "title": "Appeal to emotion"}], "description": "Why it matters: These mistakes distract from the actual support needed for a conclusion."}, {"id": "393d307e-492c-4617-ba07-e91ee9765a71", "type": "subtopic", "title": "Fallacies of evidence", "children": [{"id": "dd0666ff-5ffc-41c5-88ac-3f2e329f76b1", "type": "concept", "title": "Hasty generalization"}, {"id": "5bd7d126-52c1-4281-bdbc-8ab27c6d7007", "type": "concept", "title": "Cherry-picking"}, {"id": "10d2f3b9-aa48-4609-be4c-0e044375113a", "type": "concept", "title": "False cause"}, {"id": "602b94b3-fab0-4693-8d71-74c74b86671c", "type": "concept", "title": "Anecdotal evidence"}], "description": "Why it matters: These errors involve weak, missing, distorted, or misused evidence."}, {"id": "4660322a-fe82-4048-b993-cd6f75231098", "type": "subtopic", "title": "Cognitive biases", "children": [{"id": "2e21da61-fd76-46e4-8730-a6465f5b8764", "type": "concept", "title": "Confirmation bias"}, {"id": "aa943e35-8cb9-4773-97bf-af0ce690a671", "type": "concept", "title": "Availability heuristic"}, {"id": "3a9f49a7-8a98-40a5-93fc-ac87918b5bf3", "type": "concept", "title": "Motivated reasoning"}, {"id": "e130709e-d405-4e08-acee-0343173363df", "type": "concept", "title": "Overconfidence"}], "description": "Why it matters: Biases explain why bad reasoning can feel natural and why self-checking matters."}]}, {"id": "87bdf152-fd6e-469b-bfc7-277138f189a0", "type": "topic", "title": "Definitions, Concepts, Ambiguity, and Conceptual Analysis", "description": "Use careful language and conceptual clarification to prevent disputes from becoming confused or merely verbal.", "children": [{"id": "8a81e5e4-87cf-4305-b85f-ba76b12738f8", "type": "subtopic", "title": "Definitions", "children": [{"id": "3e9b5afd-3efc-4bf0-b0f9-9283eb7bf5e5", "type": "concept", "title": "Stipulative definitions"}, {"id": "a8300d3d-b84e-46f8-8eb7-e5b357c26be8", "type": "concept", "title": "Lexical definitions"}, {"id": "064cf01c-2623-43f1-9e53-03555ca59e3c", "type": "concept", "title": "Operational definitions"}, {"id": "746e7ad8-eb25-4de8-ba1f-b9e9cc297a8a", "type": "concept", "title": "Persuasive definitions"}], "description": "Why it matters: Definitions set the terms of debate and can clarify or distort a dispute."}, {"id": "984b029b-1a10-4824-a190-0a7104d7b683", "type": "subtopic", "title": "Ambiguity and vagueness", "children": [{"id": "15dadfa3-c654-40fa-997e-28cf8cf9ad62", "type": "concept", "title": "Equivocation"}, {"id": "9e90a622-3663-4eea-a965-b3011b11f627", "type": "concept", "title": "Amphiboly"}, {"id": "aa30ab12-1c05-4a29-a946-ce593f86e87c", "type": "concept", "title": "Borderline cases"}, {"id": "aba99a5c-33aa-407d-af54-b86082c83f03", "type": "concept", "title": "Precision and context"}], "description": "Why it matters: Students learn to detect when arguments slide between meanings or rely on unclear boundaries."}, {"id": "63e5815f-6572-4252-8ac5-6ce3f241541d", "type": "subtopic", "title": "Conceptual analysis", "children": [{"id": "24c105e1-62d1-4304-926e-6b70076eabb3", "type": "concept", "title": "Necessary conditions"}, {"id": "8cf242e8-e227-45e5-9db2-f961a82b27f3", "type": "concept", "title": "Sufficient conditions"}, {"id": "3aa3c87f-13ee-402e-88ba-d08627737dae", "type": "concept", "title": "Counterexamples"}, {"id": "c2f133f8-3cd6-4bcf-ab4b-d333a99f664c", "type": "concept", "title": "Conceptual distinctions"}], "description": "Why it matters: Conceptual analysis helps students ask what a claim really means before deciding whether it is true."}]}, {"id": "b9b7c5af-9cac-4fdc-9d3a-8807cfb8e54f", "type": "topic", "title": "Evidence, Probability, Statistics, and Quantitative Claims", "description": "Evaluate empirical claims, probabilities, statistical summaries, risk statements, and quantitative arguments.", "children": [{"id": "c693ee7d-c314-46b9-82dd-8afb9f6752fd", "type": "subtopic", "title": "Evidence quality", "children": [{"id": "ed704f0d-1194-42fc-9331-a217d798b9ae", "type": "concept", "title": "Direct and indirect evidence"}, {"id": "605622b4-d054-49d9-86ae-970191e4ea9a", "type": "concept", "title": "Triangulation"}, {"id": "bc6c1ca1-c0b6-45b4-b9b0-129279169ead", "type": "concept", "title": "Measurement quality"}, {"id": "81a25ff1-082b-4fca-a7b0-d9bb6a579ec8", "type": "concept", "title": "Replicability"}], "description": "Why it matters: Students learn to ask whether evidence is relevant, reliable, sufficient, and fairly represented."}, {"id": "6d9306b5-6f5d-4957-82d5-e5f9d755cb75", "type": "subtopic", "title": "Probability and risk", "children": [{"id": "50778c4f-b1ab-41be-9435-5d972e3f4550", "type": "concept", "title": "Base rates"}, {"id": "7ad7b5d9-c0c3-4a1f-a162-7329ccfc7ee2", "type": "concept", "title": "Conditional probability"}, {"id": "e1114dff-2f26-43f3-8b90-e40336a623de", "type": "concept", "title": "Risk versus uncertainty"}, {"id": "abfecdf2-8291-4ba0-8515-fd13af7f19e2", "type": "concept", "title": "Expected value"}], "description": "Why it matters: Probabilistic thinking prevents all-or-nothing reasoning about uncertain claims."}, {"id": "64256daf-b747-4fc7-bc75-144ca4499fb4", "type": "subtopic", "title": "Statistics in arguments", "children": [{"id": "6befafda-1eeb-42d5-b62a-f1eb92cf4511", "type": "concept", "title": "Descriptive statistics"}, {"id": "50e468e1-3624-4fed-82df-4eea9b732099", "type": "concept", "title": "Margins of error"}, {"id": "729a749e-f701-42dc-9602-026fdce157ce", "type": "concept", "title": "Correlation"}, {"id": "ccf58f9e-81ad-45ae-a485-1e2394d8671f", "type": "concept", "title": "Graphs and visual distortion"}], "description": "Why it matters: Quantitative claims must be interpreted with attention to method and context."}]}, {"id": "6daa52e9-fd72-4bff-901c-be29edafba97", "type": "topic", "title": "Scientific Reasoning, Explanation, Pseudoscience, and Causal Evidence", "description": "Apply critical thinking to scientific claims, explanatory models, experimental evidence, and pseudoscientific reasoning.", "children": [{"id": "928cdac8-ee85-4a95-9ca5-942587180839", "type": "subtopic", "title": "Scientific method and explanation", "children": [{"id": "ea2b1812-b799-4991-be92-41fdc4716772", "type": "concept", "title": "Hypotheses"}, {"id": "2ae3c506-4921-43ec-8b0c-667f7075061c", "type": "concept", "title": "Prediction"}, {"id": "ad56da7e-64cc-4900-9bfc-6427a316b695", "type": "concept", "title": "Falsifiability"}, {"id": "d09d0725-ada8-4ed5-8005-6aa499550234", "type": "concept", "title": "Mechanisms"}], "description": "Why it matters: Science is not a slogan; it is a structured way to test explanations against evidence."}, {"id": "0f292c69-5a3b-4d94-a35c-73916fd4560b", "type": "subtopic", "title": "Experimental and observational evidence", "children": [{"id": "32caf065-2ff7-4850-b893-ea677d447a85", "type": "concept", "title": "Control groups"}, {"id": "814534f1-6a68-4534-a07f-aaed2e43ac7b", "type": "concept", "title": "Randomization"}, {"id": "477f6d53-b5bf-4830-b6dc-ea875d66cbee", "type": "concept", "title": "Natural experiments"}, {"id": "14557bc5-bce7-4634-b89b-f669c7778441", "type": "concept", "title": "Observational studies"}], "description": "Why it matters: Students learn why different research designs support different levels of causal confidence."}, {"id": "8ea89d97-aded-43cc-a5cb-fa68f55e0534", "type": "subtopic", "title": "Pseudoscience detection", "children": [{"id": "d0863a5b-73f7-4302-a849-f6f099f31cf5", "type": "concept", "title": "Ad hoc rescue"}, {"id": "3101ecb0-3208-4591-af42-91ab1895b434", "type": "concept", "title": "Unfalsifiable claims"}, {"id": "c39abf7b-2341-42b0-a9f4-2f2fd8abcbe4", "type": "concept", "title": "Conspiracy insulation"}, {"id": "77c820e4-5761-42e6-a40f-4122a14e0838", "type": "concept", "title": "Misuse of scientific language"}], "description": "Why it matters: Critical thinkers must recognize claims that imitate science without accepting scientific discipline."}]}, {"id": "bc754292-cf71-4f19-a4d0-d7a8099170df", "type": "topic", "title": "Sources, Information Literacy, Testimony, Expertise, and Misinformation", "description": "Judge credibility, source quality, expertise, testimony, and the information environment responsibly.", "children": [{"id": "996eb275-3a9f-4421-b0d7-bf38e484c544", "type": "subtopic", "title": "Source evaluation", "children": [{"id": "e95bf14e-310d-4b6d-81c3-ee0609d18351", "type": "concept", "title": "Authority"}, {"id": "5a396b5f-565b-4753-8a3b-e4b7e6623693", "type": "concept", "title": "Currency"}, {"id": "bd77082d-e625-4c6c-9662-a97c2604c7da", "type": "concept", "title": "Purpose"}, {"id": "3f861782-6b5d-45b0-b69f-55e93fe03aba", "type": "concept", "title": "Evidence trail"}], "description": "Why it matters: Information literacy helps students decide whether a source deserves trust for the specific claim being made."}, {"id": "5d5a2b19-81c9-4994-aa73-50b8b381dc2b", "type": "subtopic", "title": "Expertise and testimony", "children": [{"id": "4e5caade-ce3d-40be-98aa-367951944744", "type": "concept", "title": "Relevant expertise"}, {"id": "8412b921-e676-4a39-a2b4-80bfe991fbe5", "type": "concept", "title": "Consensus"}, {"id": "ec93c85d-e781-4973-9378-579afa631634", "type": "concept", "title": "Conflicts of interest"}, {"id": "282d2d62-ea90-4361-8d57-1d8899cbdc44", "type": "concept", "title": "Epistemic dependence"}], "description": "Why it matters: Students learn when to defer to experts, when to ask questions, and how to recognize false expertise."}, {"id": "1abac07f-b17b-4150-8e29-8df064a25f75", "type": "subtopic", "title": "Misinformation environment", "children": [{"id": "250663c9-0894-473f-be58-acf5c829b0b8", "type": "concept", "title": "Disinformation"}, {"id": "886049d0-64b1-49aa-888d-1dd1aeb91fb7", "type": "concept", "title": "Misinformation"}, {"id": "fd25ccc2-147d-4c52-a6a4-f6ce113c3eb2", "type": "concept", "title": "Deepfakes and synthetic media"}, {"id": "59e60432-82ed-4026-a952-8ab2f03c6ead", "type": "concept", "title": "Fact-checking workflows"}], "description": "Why it matters: Modern reasoning requires attention to algorithms, virality, manipulation, and attention incentives."}]}, {"id": "0a76009f-2000-48c7-9aed-2da643ac06a4", "type": "topic", "title": "Rhetoric, Framing, Media Arguments, and Public Discourse", "description": "Distinguish argument from persuasion while learning how framing, narrative, and rhetoric influence belief.", "children": [{"id": "70f556a7-e36a-447b-aa17-1441ed2e8dae", "type": "subtopic", "title": "Rhetorical appeals", "children": [{"id": "365b7f9d-c175-426f-940f-76d71dbe1f62", "type": "concept", "title": "Ethos"}, {"id": "7aae3e9a-4571-49b4-b20d-51df47302f21", "type": "concept", "title": "Pathos"}, {"id": "247721af-0201-460a-9200-3e2fff3ef066", "type": "concept", "title": "Logos"}, {"id": "3c33e4d8-a8ae-4fa8-9328-84c4860cf3d0", "type": "concept", "title": "Kairos"}], "description": "Why it matters: Rhetoric can help communicate truth or manipulate audiences, so students learn to identify its role."}, {"id": "dc8a969c-0e06-46bc-96de-2a994e10e4e5", "type": "subtopic", "title": "Framing and narrative", "children": [{"id": "5813f825-4a28-4aa9-904f-eb000ce129fa", "type": "concept", "title": "Metaphors"}, {"id": "22b69f20-922d-4dd8-bd6d-37382aed2c42", "type": "concept", "title": "Loaded language"}, {"id": "5cfffdc8-a8f7-4d92-b255-7799bd3b153e", "type": "concept", "title": "Agenda-setting"}, {"id": "dee0039f-5413-4930-8aa9-ab3470073ad9", "type": "concept", "title": "Narrative structure"}], "description": "Why it matters: The way an issue is framed can shape what evidence seems relevant and what solutions seem possible."}, {"id": "46315a85-7674-4c11-a48a-de942c408f53", "type": "subtopic", "title": "Media argument analysis", "children": [{"id": "5cf8fa04-7c10-4260-901c-ac07fb0cefa0", "type": "concept", "title": "Headlines"}, {"id": "57711cca-d26d-4603-a49f-2961167ca3c5", "type": "concept", "title": "Images and charts"}, {"id": "30af82ba-efc0-4f93-bdaa-9d0bf2f531c4", "type": "concept", "title": "Sound bites"}, {"id": "ea187dd0-bb4a-4751-92b8-7000ecf54c0d", "type": "concept", "title": "Viral claims"}], "description": "Why it matters: Students practice evaluating arguments in op-eds, speeches, advertisements, social media, and visual media."}]}, {"id": "046de28c-4881-4c38-8d65-8e2a674c51ad", "type": "topic", "title": "Ethical and Civic Reasoning: Values, Tradeoffs, and Public Decisions", "description": "Apply logical and evidential standards to moral, political, legal, and policy arguments.", "children": [{"id": "97199679-5bd8-4d7a-b7fd-d7c3a0dc86e6", "type": "subtopic", "title": "Moral reasoning", "children": [{"id": "d16b244b-7f3e-4242-ad1a-2aa8f28d63c1", "type": "concept", "title": "Consequences"}, {"id": "675b3e90-3ff0-44c4-b6f1-707130a5e1cc", "type": "concept", "title": "Duties"}, {"id": "405cc76b-0dca-4f84-b1c5-66a9c42cad3f", "type": "concept", "title": "Rights"}, {"id": "850fb191-80ca-4bb7-910d-f9b192b32feb", "type": "concept", "title": "Virtues"}], "description": "Why it matters: Values need arguments too; students learn to reason about moral claims without reducing them to preference."}, {"id": "fe4e91dc-2ab9-442b-acfe-fcbc3089ca7e", "type": "subtopic", "title": "Policy reasoning", "children": [{"id": "991e05a9-dce4-4ac3-81b8-62c52c945f3f", "type": "concept", "title": "Stakeholders"}, {"id": "e0877072-fa3d-4e21-8e74-bb8c68c6ff8f", "type": "concept", "title": "Tradeoffs"}, {"id": "823b534b-330f-4fbd-a9e2-c4641bf56b50", "type": "concept", "title": "Costs and benefits"}, {"id": "0b796211-0f0e-4b21-8ab7-87aab08e4f5e", "type": "concept", "title": "Equity and justice"}], "description": "Why it matters: Public decisions require weighing evidence, values, feasibility, and unintended consequences."}, {"id": "f3d4785f-b5f3-44ba-b169-18ad19448673", "type": "subtopic", "title": "Civic disagreement", "children": [{"id": "02d2bbbe-37b8-4de2-aa4f-95e0b724285b", "type": "concept", "title": "Charitable interpretation"}, {"id": "a6767366-6666-4a34-84f7-f3404e38d45b", "type": "concept", "title": "Steel-manning"}, {"id": "6b41fc8e-7c1b-4174-ba98-95818807ef30", "type": "concept", "title": "Common ground"}, {"id": "da585280-9e6a-4f4a-94a5-bb684b9d9af9", "type": "concept", "title": "Respectful challenge"}], "description": "Why it matters: The goal is to disagree better: more honestly, more carefully, and with less contempt."}]}, {"id": "247ceb68-3b72-4ced-92f0-1046380e8c20", "type": "topic", "title": "Argument Mapping, Dialectic, Objections, Replies, and Debate", "description": "Represent complex debates visually and practice fair objection, response, revision, and dialogue.", "children": [{"id": "45cdccf2-c10e-4bb2-a7c6-b72300d82c9f", "type": "subtopic", "title": "Argument mapping", "children": [{"id": "4b716f94-f150-4068-b69b-0614a16f5882", "type": "concept", "title": "Premise-conclusion diagrams"}, {"id": "c285a30d-ac9e-4009-a62a-37091b2676e6", "type": "concept", "title": "Support and objection nodes"}, {"id": "f627976c-d491-4939-b680-77c8bf20bb59", "type": "concept", "title": "Hidden assumptions"}, {"id": "8f97474e-cf6a-41c2-86b7-b027b6e5d924", "type": "concept", "title": "Evidence links"}], "description": "Why it matters: Mapping makes complex reasoning visible and helps students locate exactly where disagreement occurs."}, {"id": "837ffa43-5a65-4c83-ad35-44cc0890aaf3", "type": "subtopic", "title": "Dialectical method", "children": [{"id": "508b3746-2228-4ea8-ba61-4b75700d1b2b", "type": "concept", "title": "Objections"}, {"id": "32afebb4-95c3-4684-8e5c-0c79ebe8b3b0", "type": "concept", "title": "Replies"}, {"id": "5cbcec6c-3181-4578-974e-06670a8255fa", "type": "concept", "title": "Revisions"}, {"id": "64100cf7-8bae-45a2-a42c-7b43d711c85a", "type": "concept", "title": "Dialectical burden"}], "description": "Why it matters: Strong reasoning improves through objections and replies."}, {"id": "74a